import {test,beforeEach} from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
const root=new URL('../',import.meta.url);
let serverCode=fs.readFileSync(new URL('src/app/lib/ai-server.js',root),'utf8').replace(/^import[^\n]+\n/,'const createClient=(...a)=>globalThis.__client(...a);\n');
const serverURL='data:text/javascript;base64,'+Buffer.from(serverCode).toString('base64');
const server=await import(serverURL);
const routeCode=fs.readFileSync(new URL('src/app/api/generate/route.js',root),'utf8').replace("'../../lib/ai-server'",JSON.stringify(serverURL));
const {POST}=await import('data:text/javascript;base64,'+Buffer.from(routeCode).toString('base64'));
let calls,queue,row;
const today=()=>new Date(Date.now()+9*3600000).toISOString().slice(0,10);
beforeEach(()=>{process.env.ANTHROPIC_API_KEY='test-only';process.env.NEXT_PUBLIC_SUPABASE_URL='https://test.invalid';process.env.SUPABASE_SERVICE_ROLE_KEY='test-only';calls=[];queue=[];row={daily_count:0,last_used_date:today()};globalThis.__client=()=>({auth:{getUser:async()=>({data:{user:{id:'test-user'}}})},from:()=>({select(){return this;},eq(){return this;},maybeSingle:async()=>({data:{...row}}),update(v){const expected={};return {eq(k,val){expected[k]=val;return this;},is(k,val){expected[k]=val;return this;},async select(){if((expected.daily_count??null)!==(row.daily_count??null)||(expected.last_used_date??null)!==(row.last_used_date??null))return {data:[]};row={...row,...v};return {data:[{ip:'test'}]};}};}})});globalThis.fetch=async(u,o)=>{calls.push(JSON.parse(o.body));let q=queue.shift();if(q instanceof Error)throw q;if(!q){const body=JSON.parse(o.body);const content=body.messages?.[0]?.content;const last=Array.isArray(content)?content.at(-1)?.text:'';try{const review=JSON.parse(last);if(review.solutions)q={stop_reason:'end_turn',content:[{type:'text',text:JSON.stringify({issues:[],reviewed_numbers:review.solutions.map(x=>x.number),missing_numbers:[]})}]};}catch{}}return Response.json(q||{content:[{type:'text',text:'{}'}],stop_reason:'end_turn'});};});
const req=b=>new Request('https://app.test/api/generate',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(b)});
const model=v=>({stop_reason:'end_turn',content:[{type:'text',text:JSON.stringify(v)}]});
const q=(id=1)=>({id,type:'객관식',question:'문제 '+id,options:['① 산소','② 물','③ 포도당','④ 빛','⑤ 질소'],answer:'① 산소',explanation:'광합성에서 산소를 생성한다.',source_quote:'광합성에서 산소를 생성한다.'});
const quiz=()=>({topic:'광합성',questions:[q(1),q(2),q(3)]});
const quizBody=()=>({operation:'quiz',sourceText:'광합성에서 산소를 생성한다.',settings:{grade:'중2',subject:'과학',difficulty:'medium',scope:'image_only',questionCount:3,englishType:'mixed'}});
test('valid quiz accepted',()=>assert.ok(server.validQuiz(quiz(),3,'광합성에서 산소를 생성한다.')));
for(const [name,change] of [['count',v=>v.questions.pop()],['duplicate id',v=>v.questions[1].id=1],['duplicate question',v=>v.questions[1].question=v.questions[0].question],['missing source',v=>v.questions[0].source_quote='없는 인용'],['answer mismatch',v=>v.questions[0].answer='① 없는 답'],['duplicate option',v=>v.questions[0].options[1]='② 산소'],['wrong type',v=>v.questions[0].type='참거짓'],['empty explanation',v=>v.questions[0].explanation='']])test('reject '+name,()=>{const v=quiz();change(v);assert.equal(server.validQuiz(v,3,'광합성에서 산소를 생성한다.'),false);});
for(const [name,b] of [['legacy',{prompt:'x'}],['too many questions',{...quizBody(),settings:{...quizBody().settings,questionCount:100}}],['empty source',{...quizBody(),sourceText:''}],['bad image',{operation:'extract',images:[{type:'image/png',base64:'AAAA'}]}],['ambiguous grade',{operation:'grade',question:{},studentAnswer:'x'}]])test('400 before upstream '+name,async()=>{const r=await POST(req(b));assert.equal(r.status,400);assert.equal(calls.length,0);assert.equal(row.daily_count,0);});
test('cross-origin rejected',async()=>{const r=await POST(new Request('https://app.test/api/generate',{method:'POST',headers:{'content-type':'application/json',origin:'https://evil.test'},body:JSON.stringify(quizBody())}));assert.equal(r.status,403);});
test('invalid JSON rejected',async()=>{const r=await POST(new Request('https://app.test/api/generate',{method:'POST',headers:{'content-type':'application/json'},body:'{'}));assert.equal(r.status,400);});
test('missing type rejected',async()=>assert.equal((await POST(new Request('https://app.test/api/generate',{method:'POST',body:'{}'}))).status,415));
test('quota enforced before AI',async()=>{row.daily_count=60;assert.equal((await POST(req(quizBody()))).status,429);assert.equal(calls.length,0);});
test('verified quiz accepted with schema and new model',async()=>{queue.push(model({error:'',...quiz()}),model({ok:true,issues:[],verified_ids:[1,2,3]}));const r=await POST(req(quizBody()));assert.equal(r.status,200);assert.equal((await r.json()).meta.verified,true);assert.equal(calls.length,2);assert.equal(calls[0].model,'claude-sonnet-5-5');assert.ok(calls[0].output_config.format.schema);assert.equal(row.daily_count,1);});
test('AI reviewer failure blocks result',async()=>{queue.push(model({error:'',...quiz()}),model({ok:false,issues:[{id:2,reason:'multiple answers'}],verified_ids:[1,3]}),model({error:'',...quiz()}),model({ok:false,issues:[{id:2,reason:'multiple answers'}],verified_ids:[1,3]}));assert.equal((await POST(req(quizBody()))).status,422);});
test('missing verification id blocks result',async()=>{queue.push(model({error:'',...quiz()}),model({ok:true,issues:[],verified_ids:[1,2]}),model({error:'',...quiz()}),model({ok:true,issues:[],verified_ids:[1,2]}));assert.equal((await POST(req(quizBody()))).status,422);});
test('max tokens blocks partial data',async()=>{queue.push({stop_reason:'max_tokens',content:[{type:'text',text:JSON.stringify({error:'',...quiz()})}]});assert.equal((await POST(req(quizBody()))).status,502);});
test('refusal is not a quiz',async()=>{queue.push({stop_reason:'refusal',content:[{type:'text',text:'no'}]});assert.equal((await POST(req(quizBody()))).status,502);});
test('malformed JSON blocked',async()=>{queue.push({stop_reason:'end_turn',content:[{type:'text',text:'{"topic":'}]});assert.equal((await POST(req(quizBody()))).status,502);});
test('unreadable image blocked',async()=>{queue.push(model({usable:false,text:'',warnings:['흐림']}));const r=await POST(req({operation:'extract',images:[{type:'image/png',base64:'iVBORw0KGgo='}]}));assert.equal(r.status,422);});
test('extract accepted and no image persisted',async()=>{queue.push(model({usable:true,text:'확인한 원문',warnings:[]}));const r=await POST(req({operation:'extract',images:[{type:'image/png',base64:'iVBORw0KGgo='}]}));assert.equal(r.status,200);assert.equal((await r.json()).text,'확인한 원문');});
test('grading score consistency enforced',async()=>{queue.push(model({result:'정답',score:0,feedback:'x'}));assert.equal((await POST(req({operation:'grade',question:{question:'1+1',answer:'2',explanation:'더하기'},studentAnswer:'2'}))).status,422);});
test('grading succeeds',async()=>{queue.push(model({result:'정답',score:100,feedback:'맞습니다.'}));assert.equal((await POST(req({operation:'grade',question:{question:'1+1',answer:'2',explanation:'더하기'},studentAnswer:'2'}))).status,200);});
test('upstream timeout returns useful 504',async()=>{queue.push(Object.assign(new Error('timeout'),{name:'TimeoutError'}));assert.equal((await POST(req(quizBody()))).status,504);});
test('compare-and-swap limits concurrent reservations',async()=>{row.daily_count=59;const outcomes=await Promise.allSettled(Array.from({length:8},()=>server.usage(req(quizBody()),true)));assert.equal(row.daily_count,60);assert.equal(outcomes.filter(o=>o.status==='fulfilled').length,1);});

test('one repair recovers rejected candidate and is reviewed again',async()=>{queue.push(model({error:'',...quiz()}),model({ok:false,issues:[{id:1,reason:'recheck'}],verified_ids:[]}),model({error:'',...quiz()}),model({ok:true,issues:[],verified_ids:[1,2,3]}));const r=await POST(req(quizBody()));assert.equal(r.status,200);assert.equal(calls.length,4);assert.equal(row.daily_count,1);});

const extractBody=(extra={})=>({operation:'extract',images:[{type:'image/png',base64:'iVBORw0KGgo='}],...extra});
test('partial extract returns readable text and original warnings even when unusable',async()=>{const data={usable:false,text:'1 + [판독 불가] = 3',warnings:['수식의 일부가 흐립니다.']};queue.push(model(data));const r=await POST(req(extractBody()));assert.equal(r.status,200);assert.deepEqual(await r.json(),data);const prompt=calls[0].messages[0].content;assert.match(prompt[1].text,/추측/);assert.match(prompt[1].text,/\[판독 불가\]/);});
test('extract separates user supplement from photo transcription',async()=>{queue.push(model({usable:true,text:'사진 원문',warnings:[]}));const r=await POST(req(extractBody({supplement:'삼각형의 변은 3cm'})));assert.equal(r.status,200);const prompt=calls[0].messages[0].content;assert.match(prompt[1].text,/사진 원문이 아니라/);assert.deepEqual(JSON.parse(prompt[2].text),{구분:'사용자 보충 설명 (사진 원문 아님)',내용:'삼각형의 변은 3cm'});});
for(const supplement of [null,42,{},'x'.repeat(5001)])test('invalid supplement rejected before quota and AI '+typeof supplement,async()=>{const r=await POST(req(extractBody({supplement})));assert.equal(r.status,400);assert.equal(calls.length,0);assert.equal(row.daily_count,0);});
test('maximum supplement accepted',async()=>{queue.push(model({usable:false,text:'[판독 불가]',warnings:['흐림']}));const r=await POST(req(extractBody({supplement:'가'.repeat(5000)})));assert.equal(r.status,200);});
test('empty and oversized extractions yield distinct 422 errors',async()=>{queue.push(model({usable:false,text:'  ',warnings:['흐림']}),model({usable:false,text:'가'.repeat(24001),warnings:['길이 초과']}));const empty=await POST(req(extractBody()));const long=await POST(req(extractBody()));assert.equal(empty.status,422);assert.equal(long.status,422);const a=await empty.json(),b=await long.json();assert.match(a.error,/찾지 못했습니다/);assert.match(b.error,/24,000자/);assert.notEqual(a.error,b.error);});

test('unreadable marker overrides usable true and preserves text and warnings',async()=>{const data={usable:true,text:'문제 1: x + [판독 불가] = 5',warnings:['숫자 확인 필요']};queue.push(model(data));const r=await POST(req(extractBody()));assert.equal(r.status,200);assert.deepEqual(await r.json(),{...data,usable:false});assert.match(calls[0].messages[0].content[1].text,/불확실한 지점이 하나라도/);});
test('extract without unreadable marker keeps usable true',async()=>{const data={usable:true,text:'문제 1: 1 + 2 = ?',warnings:['사진 가장자리 확인']};queue.push(model(data));const r=await POST(req(extractBody()));assert.equal(r.status,200);assert.deepEqual(await r.json(),data);});

const solveBody=(extra={})=>({operation:'solve',sourceText:'확인한 33번 문제와 도형 조건',grade:'중2',hintOnly:false,...extra});
const sampleImage={type:'image/png',base64:'iVBORw0KGgo='};
const solution=()=>({is_valid:true,reject_reason:'',problem:'33번 도형 문제',subject:'수학',answer:'2',steps:[{step:1,title:'계산',content:'계산하면 2입니다.'}],key_concept:'도형',tip:''});
const passedReview=()=>({ok:true,issues:[],verified_ids:[1]});
test('solve sends photo and corrected text to initial solution and independent review',async()=>{queue.push(model(solution()),model(passedReview()));const r=await POST(req(solveBody({images:[sampleImage]})));assert.equal(r.status,200);assert.equal((await r.json()).meta.verified,true);assert.equal(calls.length,2);for(const call of calls){const content=call.messages[0].content;assert.equal(content[0].source.data,sampleImage.base64);const data=JSON.parse(content[1].text);assert.equal(data.source,'확인한 33번 문제와 도형 조건');assert.match(data.photoRules,/정정한 source 텍스트를 우선/);assert.match(data.photoRules,/추측하지 말고/);} });
test('solve sends images to repair and second review after failed verification',async()=>{queue.push(model(solution()),model({ok:false,issues:[{id:1,reason:'계산 확인'}],verified_ids:[]}),model(solution()),model(passedReview()));const r=await POST(req(solveBody({images:[sampleImage,sampleImage]})));assert.equal(r.status,200);assert.equal(calls.length,4);for(const c of calls){const content=c.messages[0].content;assert.equal(content.length,3);assert.equal(content[0].type,'image');assert.equal(content[1].type,'image');assert.equal(JSON.parse(content[2].text).source,'확인한 33번 문제와 도형 조건');}});
test('text-only solve keeps string requests and review',async()=>{queue.push(model(solution()),model(passedReview()));const r=await POST(req(solveBody()));assert.equal(r.status,200);for(const c of calls){assert.equal(typeof c.messages[0].content,'string');assert.equal(JSON.parse(c.messages[0].content).source,'확인한 33번 문제와 도형 조건');}});
test('hint with photo receives the image without independent review',async()=>{queue.push(model({is_valid:true,reject_reason:'',problem:'33번',hint1:'힌트 1',hint2:'힌트 2',hint3:'힌트 3',key_concept:'도형'}));const r=await POST(req(solveBody({hintOnly:true,images:[sampleImage]})));assert.equal(r.status,200);assert.equal(calls.length,1);assert.equal(calls[0].messages[0].content[0].source.data,sampleImage.base64);});
for(const bad of [null,[],[{type:'image/png',base64:'AAAA'}],Array(6).fill(sampleImage)])test('solve invalid images rejected before usage and AI',async()=>{const r=await POST(req(solveBody({images:bad})));assert.equal(r.status,400);assert.equal(calls.length,0);assert.equal(row.daily_count,0);});
test('solve request body limit applies before usage and AI',async()=>{const r=await POST(req(solveBody({images:[sampleImage],padding:'x'.repeat(14*1024*1024)})));assert.equal(r.status,413);assert.equal(calls.length,0);assert.equal(row.daily_count,0);});

const photosBody=(extra={})=>({operation:'solve_photos',images:[sampleImage],grade:'중2',hintOnly:false,...extra});
const photoSolution=(extra={})=>({number:'33',problem:'1+1은?',is_valid:true,reason:'',answer:'2',steps:[{title:'덧셈',content:'1과 1을 더합니다.'}],key_concept:'덧셈',tip:'',...extra});
test('photo solve handles multiple problems in one direct sonnet call and preserves invalid item',async()=>{const data={solutions:[photoSolution(),photoSolution({number:'34',problem:'도형 일부 잘림',is_valid:false,reason:'도형의 길이가 보이지 않습니다.',answer:'',steps:[]}),photoSolution({number:'35-1',problem:'2+2',answer:'4'})]};queue.push(model(data));const r=await POST(req(photosBody({images:[sampleImage,sampleImage],supplement:'참고 설명'})));assert.equal(r.status,200);const out=await r.json();assert.deepEqual(out.solutions.map(({verification_warning,...v})=>v),data.solutions);assert.equal(out.verification.status,'verified');assert.equal(calls.length,2);assert.equal(calls[0].model,'claude-sonnet-5-5');assert.equal(calls[0].max_tokens,20000);assert.ok(calls[0].output_config.format.schema);const content=calls[0].messages[0].content;assert.equal(content.length,5);assert.match(content[0].text,/페이지 1.*원본/);assert.equal(content[1].source.data,sampleImage.base64);const prompt=JSON.parse(content.at(-1).text);assert.equal(prompt.supplement,'참고 설명');assert.match(prompt.task,/빠짐없이/);assert.match(prompt.rules,/추측하지 말고/);assert.equal(row.daily_count,1);});
test('photo hints use same schema and do not provide answer',async()=>{const data={solutions:[photoSolution({answer:'',key_concept:'',steps:[{title:'힌트',content:'두 수를 더해 보세요.'}]})]};queue.push(model(data));const r=await POST(req(photosBody({hintOnly:true})));assert.equal(r.status,200);const out=await r.json();assert.deepEqual(out.solutions.map(({verification_warning,...v})=>v),data.solutions);assert.equal(JSON.parse(calls[0].messages[0].content.at(-1).text).hintOnly,true);assert.equal(calls.length,2);});
for(const bad of [null,[],Array(6).fill(sampleImage),[{type:'image/png',base64:'AAAA'}]])test('photo solve invalid image before usage',async()=>{assert.equal((await POST(req(photosBody({images:bad})))).status,400);assert.equal(calls.length,0);assert.equal(row.daily_count,0);});
for(const bad of [null,0,{},'x'.repeat(5001)])test('photo solve invalid supplement before usage',async()=>{assert.equal((await POST(req(photosBody({supplement:bad})))).status,400);assert.equal(calls.length,0);assert.equal(row.daily_count,0);});
test('photo solve accepts five images and maximum supplement',async()=>{queue.push(model({solutions:[photoSolution()]}));assert.equal((await POST(req(photosBody({images:Array(5).fill(sampleImage),supplement:'가'.repeat(5000)})))).status,200);});
for(const bad of [{grade:'대1'},{hintOnly:'yes'},{hintOnly:null}])test('photo solve invalid settings before usage',async()=>{assert.equal((await POST(req(photosBody(bad)))).status,400);assert.equal(calls.length,0);assert.equal(row.daily_count,0);});
for(const [name,solutions,status] of [['empty',[],422],['over 30',Array.from({length:31},()=>photoSolution()),422],['missing number',[photoSolution({number:''})],200],['missing problem',[photoSolution({problem:''})],200],['valid without answer',[photoSolution({answer:''})],200],['valid without steps',[photoSolution({steps:[]})],200],['invalid without reason',[photoSolution({is_valid:false,reason:'',answer:'',steps:[]})],200],['invalid with answer',[photoSolution({is_valid:false,reason:'잘림',answer:'2',steps:[]})],200],['bad step',[photoSolution({steps:[{title:'',content:'풀이'}]})],200],['wrong schema',[{number:'1'}],502]])test('photo solve rejects '+name,async()=>{queue.push(model({solutions}));const r=await POST(req(photosBody()));assert.equal(r.status,status);if(status===200){const data=await r.json();assert.equal(data.solutions[0].is_valid,false);assert.equal(data.solutions[0].answer,'');assert.ok(data.solutions[0].reason);}});
test('photo hint rejects nonempty answer',async()=>{queue.push(model({solutions:[photoSolution()]}));const r=await POST(req(photosBody({hintOnly:true})));assert.equal(r.status,200);assert.equal((await r.json()).solutions[0].is_valid,false);});
test('photo solve accepts exactly 30',async()=>{queue.push(model({solutions:Array.from({length:30},(_,i)=>photoSolution({number:String(i+1)}))}));assert.equal((await POST(req(photosBody()))).status,200);});
test('photo solve rejects truncated model output',async()=>{queue.push({stop_reason:'max_tokens',content:[{type:'text',text:JSON.stringify({solutions:[photoSolution()]})}]});assert.equal((await POST(req(photosBody()))).status,502);});
test('photo solve body limit applies before usage',async()=>{assert.equal((await POST(req(photosBody({padding:'x'.repeat(14*1024*1024)})))).status,413);assert.equal(calls.length,0);assert.equal(row.daily_count,0);});

test('malformed individual solution does not discard other valid problems',async()=>{queue.push(model({solutions:[photoSolution(),photoSolution({number:'34',answer:''}),photoSolution({number:'35',answer:'4'})]}));const r=await POST(req(photosBody()));const data=await r.json();assert.equal(r.status,200);assert.deepEqual(data.solutions.map(x=>x.is_valid),[true,false,true]);assert.equal(data.solutions[2].answer,'4');});

const photoReview=(extra={})=>({issues:[],reviewed_numbers:['40'],missing_numbers:[],...extra});
test('explicit choice contradiction invalidates only the affected problem',async()=>{const a=photoSolution({number:'40',answer:'①',steps:[{title:'결론',content:'따라서 정답은 ③입니다.'}]});const b=photoSolution({number:'41',answer:'②',steps:[{title:'보기 확인',content:'①은 틀리고 정답은 ②입니다.'}]});queue.push(model({solutions:[a,b]}),model(photoReview({reviewed_numbers:['40','41']})));const r=await POST(req(photosBody()));const data=await r.json();assert.equal(data.solutions[0].is_valid,false);assert.match(data.solutions[0].reason,/정답과 풀이/);assert.equal(data.solutions[1].is_valid,true);assert.equal(data.solutions[1].answer,'②');const prompt=JSON.parse(calls[1].messages[0].content.at(-1).text);assert.equal(prompt.solutions[0].answer,'①');assert.equal(calls[1].messages[0].content[1].source.data,sampleImage.base64);assert.equal(calls[1].model,'claude-sonnet-5-5');});
for(const phrase of ['정답 ③','정답: ③','결론은 ③','결론:③'])test('explicit mismatch '+phrase,async()=>{queue.push(model({solutions:[photoSolution({number:'40',answer:'①',steps:[{title:'풀이',content:phrase}]})]}),model(photoReview()));const data=await (await POST(req(photosBody()))).json();assert.equal(data.solutions[0].is_valid,false);});
test('non-choice answer and mention of other options do not cause deterministic invalidation',async()=>{queue.push(model({solutions:[photoSolution({number:'40',answer:'①',steps:[{title:'보기',content:'③은 틀리고 ①이 맞습니다.'}]}),photoSolution({number:'41',answer:'산소',steps:[{title:'정답',content:'결론은 산소입니다.'}]})]}),model(photoReview({reviewed_numbers:['40','41']})));const data=await (await POST(req(photosBody()))).json();assert.deepEqual(data.solutions.map(x=>x.is_valid),[true,true]);});
test('independent reviewer invalidates only reported item and notes missing questions',async()=>{queue.push(model({solutions:[photoSolution({number:'35',answer:'④'}),photoSolution({number:'40',answer:'①'})]}),model(photoReview({issues:[{number:'35',reason:'그림 C와 D의 명칭이 원본과 다릅니다.'},{number:'42',reason:'사진에 있는 문항이 누락됨'}],reviewed_numbers:['35','40'],missing_numbers:['42']})));const data=await (await POST(req(photosBody()))).json();assert.equal(data.solutions[0].is_valid,false);assert.match(data.solutions[0].reason,/그림/);assert.equal(data.solutions[1].is_valid,true);assert.deepEqual(data.verification.missing_numbers,['42']);assert.equal(data.verification.status,'partial');});
test('review failure preserves candidate and gives per-item warning',async()=>{queue.push(model({solutions:[photoSolution({number:'40'})]}),Object.assign(new Error('timeout'),{name:'TimeoutError'}));const r=await POST(req(photosBody()));const data=await r.json();assert.equal(r.status,200);assert.equal(data.solutions[0].answer,'2');assert.match(data.solutions[0].verification_warning,/검증하지 못했습니다/);assert.equal(data.verification.status,'failed');});
