const streamReq=(body,signal)=>new Request('https://app.test/api/generate',{method:'POST',headers:{'content-type':'application/json',accept:'application/x-ndjson'},body:JSON.stringify(body),signal});
const deferred=()=>{let resolve,reject;const promise=new Promise((a,b)=>{resolve=a;reject=b});return {promise,resolve,reject};};
const tick=()=>new Promise(resolve=>setImmediate(resolve));
const readStreamEvent=async reader=>{const item=await reader.read();if(item.done)return null;const line=new TextDecoder().decode(item.value);assert.ok(line.endsWith('\n'));return JSON.parse(line);};
const observeTimers=()=>{const originalSet=globalThis.setTimeout,originalClear=globalThis.clearTimeout;const pending=new Map(),cleared=[];globalThis.setTimeout=(fn,ms,...args)=>{const id=originalSet(fn,ms,...args);if(ms>=89000)pending.set(id,{fn,ms});return id;};globalThis.clearTimeout=id=>{if(pending.has(id)){cleared.push(id);pending.delete(id);}return originalClear(id);};return {pending,cleared,restore(){for(const id of pending.keys())originalClear(id);globalThis.setTimeout=originalSet;globalThis.clearTimeout=originalClear;}};};

test('NDJSON sends checked candidates before delayed independent review and final complete after',async()=>{
 const gate=deferred(),items=[photoSolution({number:'40',answer:'①',steps:[{title:'결론',content:'정답은 ③입니다.'}]}),photoSolution({number:'41',answer:'2'})];let invoked=0;
 globalThis.fetch=async(u,o)=>{calls.push(JSON.parse(o.body));if(++invoked===1)return Response.json(model({solutions:items}));await gate.promise;return Response.json(model(photoReview({reviewed_numbers:['40','41']})));};
 const timers=observeTimers();try{
  const response=await POST(streamReq(photosBody({detailImages:[jpegDetail()]})));assert.equal(response.status,200);assert.match(response.headers.get('content-type'),/^application\/x-ndjson/);assert.equal(response.headers.get('cache-control'),'no-store');assert.equal(timers.pending.size,1);
  const reader=response.body.getReader();const event=await readStreamEvent(reader);assert.equal(event.type,'candidate');assert.deepEqual(Object.keys(event.data),['solutions']);assert.equal(event.data.solutions[0].is_valid,false);assert.equal(event.data.solutions[0].answer,'');assert.equal(event.data.solutions[1].answer,'2');assert.equal(row.daily_count,1);
  const finalRead=readStreamEvent(reader);let finished=false;finalRead.then(()=>{finished=true});await tick();assert.equal(finished,false);assert.equal(calls.length,2);assert.equal(timers.pending.size,1);
  gate.resolve();const complete=await finalRead;assert.equal(complete.type,'complete');assert.equal(complete.data.verification.status,'verified');assert.equal(complete.data.solutions[0].is_valid,false);assert.equal(await readStreamEvent(reader),null);assert.equal(timers.pending.size,0);assert.equal(new Set(timers.cleared).size,timers.cleared.length);assert.equal(row.daily_count,1);
  assert.deepEqual(calls[0].messages[0].content.slice(0,-1),calls[1].messages[0].content.slice(0,-1));
 }finally{gate.resolve();timers.restore();}
});
test('NDJSON review failure retains candidate and sends failed complete',async()=>{queue.push(model({solutions:[photoSolution()]}),new Error('upstream secret must not leak'));const r=await POST(streamReq(photosBody()));const events=(await r.text()).trim().split('\n').map(JSON.parse);assert.deepEqual(events.map(x=>x.type),['candidate','complete']);assert.equal(events[1].data.verification.status,'failed');assert.match(events[1].data.solutions[0].verification_warning,/검증하지 못했습니다/);assert.equal(row.daily_count,1);});
test('NDJSON first candidate failure uses safe error event',async()=>{queue.push(new Error('secret data must never appear'));const r=await POST(streamReq(photosBody()));const events=(await r.text()).trim().split('\n').map(JSON.parse);assert.equal(events.length,1);assert.equal(events[0].type,'error');assert.doesNotMatch(events[0].message,/secret/);assert.equal(row.daily_count,1);assert.equal(calls.length,1);});
