test('already aborted signal never reserves or calls AI',async()=>{const ac=new AbortController();ac.abort();const r=await POST(streamReq(photosBody(),ac.signal));const event=await r.json();assert.equal(event.type,'error');assert.equal(row.daily_count,0);assert.equal(calls.length,0);});
test('reader cancel before candidate aborts upstream and cleans ownership once',async()=>{const timers=observeTimers();let upstream;globalThis.fetch=async(u,o)=>{calls.push(JSON.parse(o.body));upstream=o.signal;return new Promise(()=>{});};try{const r=await POST(streamReq(photosBody()));const reader=r.body.getReader();assert.equal(calls.length,1);assert.equal(timers.pending.size,1);await reader.cancel();await tick();assert.equal(upstream.aborted,true);assert.equal(timers.pending.size,0);assert.equal(new Set(timers.cleared).size,timers.cleared.length);assert.equal(calls.length,1);assert.equal(row.daily_count,1);}finally{timers.restore();}});
test('external abort after candidate aborts review and closes without a complete event',async()=>{const timers=observeTimers(),ac=new AbortController();let upstream;globalThis.fetch=async(u,o)=>{calls.push(JSON.parse(o.body));upstream=o.signal;if(calls.length===1)return Response.json(model({solutions:[photoSolution()]}));return new Promise(()=>{});};try{const r=await POST(streamReq(photosBody(),ac.signal));const reader=r.body.getReader();assert.equal((await readStreamEvent(reader)).type,'candidate');await tick();assert.equal(calls.length,2);ac.abort();assert.equal(await readStreamEvent(reader),null);assert.equal(upstream.aborted,true);assert.equal(timers.pending.size,0);assert.equal(row.daily_count,1);}finally{timers.restore();}});
test('deadline remains live after response and yields failed complete after candidate',async()=>{const timers=observeTimers();let upstream;globalThis.fetch=async(u,o)=>{calls.push(JSON.parse(o.body));upstream=o.signal;if(calls.length===1)return Response.json(model({solutions:[photoSolution()]}));return new Promise(()=>{});};try{const r=await POST(streamReq(photosBody()));const reader=r.body.getReader();assert.equal((await readStreamEvent(reader)).type,'candidate');await tick();assert.equal(timers.pending.size,1);const remaining=[...timers.pending.values()][0];assert.ok(remaining.ms<=115000&&remaining.ms>110000);remaining.fn();const event=await readStreamEvent(reader);assert.equal(event.type,'complete');assert.equal(event.data.verification.status,'failed');assert.equal(await readStreamEvent(reader),null);assert.equal(upstream.aborted,true);assert.equal(timers.pending.size,0);assert.equal(calls.length,2);}finally{timers.restore();}});

test('NDJSON malformed request receives error without usage',async()=>{const r=await POST(new Request('https://app.test/api/generate',{method:'POST',headers:{'content-type':'application/json',accept:'application/x-ndjson'},body:'{'}));assert.match(r.headers.get('content-type'),/application\/x-ndjson/);assert.equal((await r.json()).type,'error');assert.equal(row.daily_count,0);assert.equal(calls.length,0);});
test('deadline before candidate emits error and cleans stream',async()=>{const timers=observeTimers();globalThis.fetch=async(u,o)=>{calls.push(JSON.parse(o.body));return new Promise(()=>{});};try{const r=await POST(streamReq(photosBody()));const reader=r.body.getReader();assert.equal(timers.pending.size,1);[...timers.pending.values()][0].fn();const event=await readStreamEvent(reader);assert.equal(event.type,'error');assert.match(event.message,/초과/);assert.equal(await readStreamEvent(reader),null);assert.equal(timers.pending.size,0);assert.equal(calls.length,1);}finally{timers.restore();}});
test('reader cancel after candidate aborts review and cleans once',async()=>{const timers=observeTimers();let signal;globalThis.fetch=async(u,o)=>{calls.push(JSON.parse(o.body));signal=o.signal;if(calls.length===1)return Response.json(model({solutions:[photoSolution()]}));return new Promise(()=>{});};try{const r=await POST(streamReq(photosBody()));const reader=r.body.getReader();assert.equal((await readStreamEvent(reader)).type,'candidate');await tick();await reader.cancel();await tick();assert.equal(signal.aborted,true);assert.equal(timers.pending.size,0);assert.equal(new Set(timers.cleared).size,timers.cleared.length);assert.equal(calls.length,2);assert.equal(row.daily_count,1);}finally{timers.restore();}});
test('request abort while reserving usage does not start an AI call',async()=>{const ac=new AbortController(),gate=deferred(),started=deferred();globalThis.__client=()=>({from:()=>({select(){return this},eq(){return this},async maybeSingle(){started.resolve();await gate.promise;return {data:{...row}}},update(v){return {eq(){return this},is(){return this},async select(){row={...row,...v};return {data:[{}]}}}}})});const pending=POST(streamReq(photosBody(),ac.signal));await started.promise;ac.abort();gate.resolve();const r=await pending;assert.equal((await r.json()).type,'error');assert.equal(calls.length,0);assert.equal(row.daily_count,1);});

