test('quiz_photos cancellation during review aborts and never repairs',async()=>{const ac=new AbortController(),timers=observeTimers();let upstream;globalThis.fetch=async(u,o)=>{calls.push(JSON.parse(o.body));upstream=o.signal;if(calls.length===1)return Response.json(model(photoQuizCandidate()));return new Promise(()=>{});};try{const pending=POST(new Request('https://app.test/api/generate',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(photoQuizBody()),signal:ac.signal}));while(calls.length<2)await tick();assert.equal(timers.pending.size,1);assert.ok([...timers.pending.values()][0].ms>110000);ac.abort();const r=await pending;assert.equal(r.status,504);assert.equal(upstream.aborted,true);assert.equal(timers.pending.size,0);assert.equal(calls.length,2);assert.equal(row.daily_count,1);}finally{timers.restore();}});

test('quiz_photos rejects combined oversized image payload before reservation',async()=>{const big=Buffer.alloc(1570000,1);big.set([255,216,255],0);const image={type:'image/jpeg',base64:big.toString('base64')};const r=await POST(req(photoQuizBody({images:[image,image]})));assert.equal(r.status,413);assert.equal(calls.length,0);assert.equal(row.daily_count,0);});
test('quiz_photos never releases result if independent reviewer omits an id twice',async()=>{queue.push(model(photoQuizCandidate()),model(quizReview({verified_ids:[1,2]})),model(photoQuizCandidate()),model(quizReview({verified_ids:[1,2]})));const r=await POST(req(photoQuizBody()));assert.equal(r.status,422);assert.equal(calls.length,4);assert.equal(row.daily_count,1);});
test('quiz_photos timeout before first result aborts and releases timer',async()=>{const timers=observeTimers();let upstream;globalThis.fetch=async(u,o)=>{calls.push(JSON.parse(o.body));upstream=o.signal;return new Promise(()=>{});};try{const pending=POST(req(photoQuizBody()));while(!calls.length)await tick();assert.equal(timers.pending.size,1);[...timers.pending.values()][0].fn();const r=await pending;assert.equal(r.status,504);assert.equal(upstream.aborted,true);assert.equal(timers.pending.size,0);assert.equal(calls.length,1);assert.equal(row.daily_count,1);}finally{timers.restore();}});

test('photo quiz independent review checks grade, subject, difficulty and scope and verified means AI review only',async()=>{
 const setting={...quizBody().settings,grade:'중3',subject:'과학',difficulty:'hard',scope:'image_plus'};const v=photoQuizCandidate();v.questions[0].question='[확장] 문제 1';queue.push(model(v),model(quizReview()));const r=await POST(req(photoQuizBody({settings:setting})));assert.equal(r.status,200);const out=await r.json();assert.deepEqual(Object.keys(out.meta).sort(),['elapsedMs','model','partial','requested_count','returned_count','review_method','verified']);assert.equal(out.meta.verified,true);const prompt=JSON.parse(calls[1].messages[0].content.at(-1).text);assert.deepEqual(prompt.settings,setting);for(const term of ['settings.grade','settings.subject','settings.difficulty','학년','과목','난이도','image_only','image_plus','[확장]','source_quote','서버의 자동 문자열 판정이 아닌','독립 AI의 시각 대조','무오류를 보장하지 않습니다'])assert.ok(prompt.task.includes(term),term);
});
