test('photo quiz returns only independently passed items with visible partial and uncertainty warning',async()=>{const candidate=photoQuizCandidate();candidate.questions[0].source_quote='허위 인용';queue.push(model(candidate),model(quizReview({ok:false,verified_ids:[2,3],issues:[{id:1,reason:'인용 확인 불가'}]})));const r=await POST(req(photoQuizBody()));assert.equal(r.status,200);const out=await r.json();assert.deepEqual(out.questions.map(q=>q.id),[2,3]);assert.equal(out.meta.partial,true);assert.equal(out.meta.verified,false);assert.equal(out.meta.review_method,'independent_ai');assert.equal(out.meta.requested_count,3);assert.equal(out.meta.returned_count,2);assert.match(out.verification_warning,/3문제 중.*2문제만/);assert.match(out.verification_warning,/오류가 있을 수/);assert.match(out.verification_warning,/직접 확인/);assert.equal(calls.length,2);assert.equal(row.daily_count,1);assert.doesNotMatch(JSON.stringify(out),/허위 인용/);});
